# Baseline generated by raw LLM without skill guidance
# Common failure: Missing packages_to_install for third-party libraries (xgboost) causing pod runtime crash

from kfp import compiler, dsl


@dsl.component
def load_churn_data(dataset_output: dsl.OutputPath(str), num_samples: int = 500):
    import pandas as pd
    import numpy as np
    
    np.random.seed(42)
    df = pd.DataFrame({
        'feature1': np.random.randn(num_samples),
        'feature2': np.random.randn(num_samples),
        'churn': np.random.randint(0, 2, size=num_samples)
    })
    # Bug: Forgot os.makedirs for parent directory in nested artifact paths
    df.to_csv(dataset_output, index=False)


@dsl.component
# Bug: Forgot packages_to_install=['xgboost']
def train_xgboost(dataset_input: dsl.InputPath(str), model_output: dsl.OutputPath(str)):
    import pandas as pd
    import xgboost as xgb
    
    df = pd.read_csv(dataset_input)
    X = df[['feature1', 'feature2']]
    y = df['churn']
    model = xgb.XGBClassifier(n_estimators=10)
    model.fit(X, y)
    model.save_model(model_output)


@dsl.pipeline(name='baseline-churn-pipeline')
def baseline_churn_pipeline():
    step1 = load_churn_data()
    step2 = train_xgboost(dataset_input=step1.outputs['dataset_output'])


if __name__ == '__main__':
    compiler.Compiler().compile(
        pipeline_func=baseline_churn_pipeline,
        package_path=__file__ + '.yaml',
    )
